INSERT INTO Language_ko_KR (Tag, Text)
VALUES	('TXT_KEY_BUILDING_BRAZIL_EMBRAPA',			'엠브라파'),
		('TXT_KEY_BUILDING_BRAZIL_EMBRAPA_TEXT',		'엠브라파는 브라질 농무부에 소속된 국유 연구 기업입니다. 1973년 4월 26일 설립된 이래로 브라질 농업, 특히 가축에 관한 기술, 지식, 기술-과학 정보를 개발하는 데 전념해 왔습니다. 엠브라파의 조직 구조는 연구 부서나 서비스 부서로 나눌 수 있는 46개의 센터와 기업의 본사를 구성하는 17개의 중앙 부서로 구성되어 있습니다. 이러한 연구 센터는 브라질의 거의 모든 주에 걸쳐 분포되어 있습니다.'),
		('TXT_KEY_BUILDING_BRAZIL_EMBRAPA_STRATEGY',	'엠브라파는 연구실과 같은 과학 보너스 외에도 관광, 문화, 심지어 골드에 대한 보너스를 제공합니다. 브라질 소방목 야영지와 이를 건설한 정글 및/또는 숲 타일은 추가 과학을 받고, 관광이나 문화와 골드도 받습니다. 목초지와 식물 보너스 자원도 브라질 소방목 야영지와 마찬가지로 향상됩니다. 이러한 보너스는 브라질 소방목 야영지가 많고 타일의 문화를 관광으로 전환할 수 있는 방법을 갖춘 대규모 문명에 가장 효과적입니다. 마지막으로 도시는 총 식량의 일정 비율로 관광을 얻어 문명에 대한 가치가 증가합니다.'),
		('TXT_KEY_BUILDING_BRAZIL_EMBRAPA_HELP', '이 도시에서 작업하는 [ICON_RES_OIL] 석유, [ICON_RES_ALUMINUM] 알루미늄, [ICON_RES_URANIUM] 우라늄, 아카데미에서 얻는 [ICON_RESEARCH] 과학이 +4 증가합니다.[NEWLINE][NEWLINE]이 도시에서 작업하는 브라질 소방목 야영지, 목초지, [ICON_RES_BANANA] 바나나, [ICON_RES_RICE] 쌀, [ICON_RES_MAIZE] 옥수수, 밀에서 [ICON_GOLD] 골드, [ICON_RESEARCH] 과학, [ICON_CULTURE] 문화가 +2 증가합니다.이 도시에서 작업하는 숲과 정글 타일에서 [ICON_RESEARCH] 과학과 [ICON_TOURISM] 관광이 +1 증가합니다. 도시에서 생산되는 [ICON_FOOD] 식량의 5%는 [ICON_TOURISM] 관광으로 전환됩니다.[NEWLINE][NEWLINE]이 도시에서는 병원, 공장, 의학 연구소에서 [ICON_RESEARCH] 과학이 +4만큼 증가하고, [ICON_GREAT_SCIENTIST] 위대한 과학자가 33% 더 빨리 생산됩니다.[NEWLINE][NEWLINE][ICON_RESEARCH] 문맹으로 인한 [ICON_HAPPINESS_3] 불행이 -1 감소합니다.');